// Reverse map: folder -> type id
const FOLDER_TO_TYPE = {};
for (const [id, type] of Object.entries(DOC_TYPES)) {
    FOLDER_TO_TYPE[type.folder] = id;
}
// Toll & Veil shares the 'other-games' type with Kon'reh but lives in its
// own folder, so it needs a second folder->type mapping the auto-built
// loop above (one folder per DOC_TYPES entry) can't express.
FOLDER_TO_TYPE['tollveil'] = 'other-games';

// ─── Type order for sorting ──────────────────────────────────
const TYPE_ORDER = ['core', 'quickstart', 'players-guide', 'gm-guide', 'resources', 'adventures', 'expansions', 'anthology', 'travel', 'design', 'other-games', 'uploaded', 'other'];

// ============================================================
// STATE
// ============================================================

let allDocs = [];
let currentDocPath = null;
let isDarkMode = false;
let container = null;

// Multi-page "book" document state. currentBookDoc is the manifest entry
// (with its `pages` array); currentChapterIndex is -1 for the table of
// contents view, or an index into currentBookDoc.pages otherwise.
let currentBookDoc = null;
let currentChapterIndex = -1;

// ============================================================
// HELPERS
// ============================================================

function getDocTitle(file) {
    return file
        .replace(/\.html$/, '')
        .replace(/Fates_-_Edge_-_-/g, '')
        .replace(/_/g, ' ')
        .replace(/-/g, ' ')
        .replace(/\b\w/g, l => l.toUpperCase())
        .trim();
}

function getDocTypeFromFile(file) {
  const adventurePatterns = ['Saga', 'Dreams', 'Serpent', 'Blood', 'Carnival', 'Adventure', 'Coil', 'Lantern', 'Chronicle'];
  if (adventurePatterns.some(p => file.includes(p))) return 'adventures';
  if (file.includes('Screen') || file.includes('GM')) return 'resources';
  if (file.includes('Reference') || file.includes('SRD') || file.includes('Essentials') || file.includes('Essential')) return 'core';
  return 'other';
}

function resolveFullPath(doc) {
    if (!doc) return null;
    if (doc.fullPath) return doc.fullPath;

    // Prefer the manifest's own "path" field when present -- it's written
    // by generate-manifests.js from the actual folder a doc was found in,
    // so it's authoritative and doesn't depend on this file's DOC_TYPES map
    // staying manually in sync with that script's CATEGORY_MAP. Relying on
    // DOC_TYPES here instead (as this used to) silently dropped the
    // subfolder -- and therefore pointed at the wrong URL -- for any
    // category (e.g. "anthology") that had been added to the manifest
    // generator but not mirrored into DOC_TYPES below.
    if (doc.path && doc.file) {
        const path = doc.path.endsWith('/') ? doc.path : doc.path + '/';
        return path + doc.file.replace(/^\/+/, '');
    }

    if (doc.file) {
        const file = doc.file.replace(/^\/+|\/+$/g, '');
        let folder = doc.folder || '';
        if (doc.type && DOC_TYPES[doc.type]) {
            folder = DOC_TYPES[doc.type].folder;
        }
        if (!folder || folder === 'core') {
            return DOCS_BASE_PATH + file;
        }
        return DOCS_BASE_PATH + folder + '/' + file;
    }
    return null;
}

function normalizeFileName(file) {
    if (!file) return file;
    return file.trim().replace(/^\/+|\/+$/g, '').replace(/\s+/g, ' ');
}

function docsAreSame(docA, docB) {
    if (!docA || !docB) return false;
    if (docA.fullPath && docB.fullPath) {
        return docA.fullPath === docB.fullPath;
    }
    if (docA.file && docB.file) {
        return normalizeFileName(docA.file) === normalizeFileName(docB.file);
    }
    return false;
}

// FIX: this used to flag any document containing the loose prose phrase
// "Fate's Edge Toolkit" as "the SPA shell, not a real document" -- but
// several real documents (like the Kon'reh Definitive Guide, whose own
// subtitle reads "Fate's Edge Toolkit Edition") legitimately contain that
// phrase in their own text. That was a raw substring search over the
// whole HTML string, which is fragile in both directions: it can
// false-positive on a doc that merely *mentions* the shell's markers in
// its own prose or an unescaped code sample, and it can false-negative
// the moment the shell's markup changes shape without every indicator
// string being updated to match (one of the three indicators here,
// `<div id="app">`, doesn't actually exist anywhere in index.html --
// the real mount point is `id="app-content"` -- so that check has
// silently never matched anything).
//
// This now parses the fetched HTML with DOMParser and looks for the
// shell's actual structural elements (by id/selector, not string
// position), and requires at least two independent signals to agree
// before calling it the SPA shell. Parsing as an inert DOM document also
// means a doc that merely *prints* these markers as escaped text in a
// code sample can't trigger a false positive the way substring matching
// could, since escaped text never becomes a real element node.
function isSpaContent(html) {
    if (!html) return false;
    try {
        const parsed = new DOMParser().parseFromString(html, 'text/html');
        const hasAppMount = !!parsed.getElementById('app-content');
        const hasToastHost = !!parsed.getElementById('toast-container');
        const hasAppScript = !!parsed.querySelector('script[type="module"][src*="app.js"]');
        const signals = [hasAppMount, hasToastHost, hasAppScript].filter(Boolean).length;
        return signals >= 2;
    } catch (_) {
        // If it doesn't even parse as HTML, it's not the SPA shell.
        return false;
    }
}

// ─── HTML sanitization ───────────────────────────────────────────
// Documents rendered here can come from three places: the build's own
// /data/docs/ tree (trusted), a user's "Upload Doc" action (untrusted --
// any local file the user picks), and localStorage replay of a previous
// upload. All three go through this before ever touching innerHTML.
//
// This used to only strip <script> and <base> tags via regex, which
// leaves the door wide open to inline event handlers
// (onerror/onload/onclick/...), javascript: URLs, <iframe>/<object>/
// <embed>/<link>/<meta http-equiv="refresh">/<form> content, and is
// generally unreliable since regex can't correctly parse nested or
// malformed HTML. This now parses with DOMParser (inert -- nothing in
// it executes or loads network resources during parsing) and removes
// disallowed elements and attributes structurally instead.
const SANITIZE_DISALLOWED_TAGS = ['script', 'iframe', 'object', 'embed', 'link', 'base', 'meta', 'applet', 'form'];
const SANITIZE_URL_ATTRS = ['href', 'src', 'action', 'formaction', 'xlink:href'];

function isDangerousUrl(value) {
    const v = (value || '').trim().toLowerCase();
    if (v.startsWith('javascript:') || v.startsWith('vbscript:')) return true;
    // data: URIs are legitimate for embedded images/fonts in a
    // self-contained doc; only block the executable/document kinds.
    if (v.startsWith('data:') && !/^data:(image\/|font\/|application\/font)/.test(v)) return true;
    return false;
}

function sanitizeHtml(html) {
    if (!html) return '';
    let parsed;
    try {
        parsed = new DOMParser().parseFromString(html, 'text/html');
    } catch (_) {
        // Parsing itself failed -- don't render anything rather than
        // fall back to unsanitized raw HTML.
        return '';
    }

    SANITIZE_DISALLOWED_TAGS.forEach(tag => {
        parsed.querySelectorAll(tag).forEach(el => el.remove());
    });

    parsed.querySelectorAll('*').forEach(el => {
        Array.from(el.attributes).forEach(attr => {
            const name = attr.name.toLowerCase();
            if (name.startsWith('on')) {
                el.removeAttribute(attr.name);
                return;
            }
            if (name === 'srcdoc') {
                el.removeAttribute(attr.name);
                return;
            }
            if (SANITIZE_URL_ATTRS.includes(name) && isDangerousUrl(attr.value)) {
                el.removeAttribute(attr.name);
            }
        });
    });

    return parsed.body ? parsed.body.innerHTML : '';
}

function getDocType(doc) {
    if (doc.type && DOC_TYPES[doc.type]) return doc.type;
    if (doc.folder && FOLDER_TO_TYPE[doc.folder]) return FOLDER_TO_TYPE[doc.folder];
    if (doc.fullPath) {
        const pathParts = doc.fullPath.split('/');
        for (const part of pathParts) {
            if (FOLDER_TO_TYPE[part]) return FOLDER_TO_TYPE[part];
        }
    }
    if (doc.file) {
        return getDocTypeFromFile(doc.file);
    }
    return 'other';
}

function getTypeLabel(typeId) {
    return DOC_TYPES[typeId]?.label || DOC_TYPES.other.label;
}

function getTypeIcon(typeId) {
    return DOC_TYPES[typeId]?.icon || DOC_TYPES.other.icon;
}

function getTypeClass(typeId) {
    return typeId || 'other';
}

