// ============================================================
// LOAD DOCS
// ============================================================

export function loadDocs() {
    const container = document.getElementById('doc-list');
    if (!container) return;

    // Try localStorage cache first
    try {
        const cached = localStorage.getItem(CACHE_KEY);
        if (cached) {
            const data = JSON.parse(cached);
            if (data.docs && data.docs.length > 0) {
                console.log(`📄 Using cached doc list (${data.docs.length} items)`);
                allDocs = data.docs;
                populateTypeFilter(allDocs);
                applyDocsFilter();
                updateDocStats(allDocs.length);
                updateTotalCount();
                return;
            }
        }
    } catch (_) {}

    // Try loading /data/docs/manifest.json first (generated by build)
    console.log('📄 No cache found, loading manifest.json…');
    fetch(MANIFEST_PATH)
        .then(res => {
            if (!res.ok) throw new Error('manifest.json not found');
            return res.json();
        })
        .then(manifest => {
            let docs = [];
            if (Array.isArray(manifest)) {
                // Simple array of slugs → build doc objects
                docs = manifest.map(slug => {
                    const file = slug + '.html';
                    const title = getDocTitle(file);
                    const type = getDocTypeFromFile(file);
                    return {
                        id: slug,
                        title: title,
                        file: file,
                        type: type,
                        folder: DOC_TYPES[type]?.folder || '',
                        path: '/data/docs/',
                        category: type,
                        categoryLabel: getTypeLabel(type),
                        core: type === 'core',
                        active: true,
                        fullPath: '/data/docs/' + file
                    };
                });
            } else if (manifest.documents && Array.isArray(manifest.documents)) {
                // Rich manifest format (like manifest-core.json)
                docs = manifest.documents.map(doc => {
                    const type = doc.category || doc.type || 'other';
                    doc.type = type;
                    doc.folder = DOC_TYPES[type]?.folder || '';
                    doc.fullPath = doc.fullPath || resolveFullPath(doc);
                    return doc;
                });
            }

            if (docs.length > 0) {
                allDocs = docs;
                try {
                    localStorage.setItem(CACHE_KEY, JSON.stringify({ docs: allDocs, timestamp: Date.now() }));
                } catch (_) {}
                console.log(`📚 Loaded ${allDocs.length} documents from manifest.json`);
                populateTypeFilter(allDocs);
                applyDocsFilter();
                updateDocStats(allDocs.length);
                updateTotalCount();
                return;
            }
            throw new Error('No documents in manifest');
        })
        .catch(() => {
            // Fall back to manifest-core.json
            console.log('📄 manifest.json not found, falling back to manifest-core.json…');
            fetch(MANIFEST_CORE_PATH)
                .then(res => {
                    if (!res.ok) throw new Error('manifest-core.json not found');
                    return res.json();
                })
                .then(manifest => {
                    const docs = (manifest.documents || []).map(doc => {
                        const type = doc.category || doc.section || 'other';
                        doc.type = type;
                        doc.folder = DOC_TYPES[type]?.folder || '';
                        doc.fullPath = resolveFullPath(doc);
                        return doc;
                    });
                    if (docs.length > 0) {
                        allDocs = docs;
                        try {
                            localStorage.setItem(CACHE_KEY, JSON.stringify({ docs: allDocs, timestamp: Date.now() }));
                        } catch (_) {}
                        console.log(`📚 Loaded ${allDocs.length} documents from manifest-core.json (fallback)`);
                        populateTypeFilter(allDocs);
                        applyDocsFilter();
                        updateDocStats(allDocs.length);
                        updateTotalCount();
                    } else {
                        showEmptyState();
                    }
                })
                .catch(() => {
                    console.warn('📄 No manifest found, showing empty state.');
                    showEmptyState();
                });
        });
}

function showEmptyState() {
    const container = document.getElementById('doc-list');
    if (!container) return;
    container.innerHTML = `
        <div class="empty-state" style="color:var(--text2);text-align:center;padding:2rem;font-style:italic;min-width:100%;">
            <div style="font-size:2rem;">📭</div>
            <p>No documents found.</p>
            <p class="text-muted" style="font-size:0.85rem;">Use "Scan Filesystem" to discover HTML documents in /data/docs/ and its subdirectories.</p>
        </div>
    `;
    allDocs = [];
    updateDocStats(0);
    updateTotalCount();
}

// ============================================================
// SAVE CACHE
// ============================================================

function saveCache() {
    try {
        localStorage.setItem(CACHE_KEY, JSON.stringify({
            docs: allDocs,
            timestamp: Date.now()
        }));
    } catch (_) {}
}

// ============================================================
// SCAN FILESYSTEM – Discover HTML documents in /data/docs/ and subdirectories
// ============================================================

export async function scanFilesystem() {
    const discoveredDocs = [];
    const existingDocs = allDocs.slice();
    const existingFileNames = new Set(existingDocs.map(d => d.file));

    // ─── Step 1: Known core files (in /data/docs/) ────────────────
    const knownCoreFiles = [
        { id: 'srd', title: "Fate's Edge Systems Reference Document", file: 'Fates_-_Edge_-_-Systems_-_Reference_-_Document.html', type: 'core' },
        { id: 'essentials', title: "Fate's Edge Essentials", file: 'Fates_-_Edge_-_-Essentials.html', type: 'core' },
        { id: 'essential_gm_screen', title: "Fate's Edge Essential GM Screen", file: 'Fates_-_Edge_-_-Game_-_Master_-_Screen.html', type: 'resources' }
    ];

    for (const known of knownCoreFiles) {
        const path = DOCS_BASE_PATH + known.file;
        try {
            const res = await fetch(path, { method: 'HEAD' });
            if (res.ok) {
                const exists = existingDocs.some(d => d.file === known.file);
                if (!exists) {
                    const type = known.type || 'core';
                    const doc = {
                        id: known.id,
                        title: known.title,
                        file: known.file,
                        type: type,
                        folder: DOC_TYPES[type]?.folder || '',
                        path: DOCS_BASE_PATH,
                        category: type,
                        categoryLabel: getTypeLabel(type),
                        categoryClass: getTypeClass(type),
                        core: type === 'core',
                        active: true,
                        adventure: type === 'adventures',
                        tier: null,
                        sessions: null,
                        type_label: null
                    };
                    doc.fullPath = resolveFullPath(doc);
                    discoveredDocs.push(doc);
                    console.log(`📄 Discovered: ${known.file} (${type})`);
                }
            }
        } catch (_) { /* ignore */ }
    }

    // ─── Step 2: Known adventure files ────────────────────────────
    const knownAdventureFiles = [
        { id: 'blood_silk_saga', title: 'Blood and Silk: The Complete Saga', file: 'Fates_-_Edge_-_-Bloood-_-and-_-Silk-_-Saga.html' },
        { id: 'carnival_broken_dreams', title: 'The Carnival of Broken Dreams', file: 'Fates_-_Edge_-_-Canival-_-of-_-Broken-_-Dreams.html' },
        { id: 'serpents_coil', title: "The Serpent's Coil", file: "Fates_-_Edge_-_-The-_-Serpent's-_-Coil.html" }
    ];

    for (const known of knownAdventureFiles) {
        const path = DOCS_BASE_PATH + 'adventures/' + known.file;
        try {
            const res = await fetch(path, { method: 'HEAD' });
            if (res.ok) {
                const exists = existingDocs.some(d => d.file === known.file);
                if (!exists) {
                    const type = 'adventures';
                    const doc = {
                        id: known.id,
                        title: known.title,
                        file: known.file,
                        type: type,
                        folder: DOC_TYPES[type]?.folder || '',
                        path: DOCS_BASE_PATH,
                        category: type,
                        categoryLabel: getTypeLabel(type),
                        categoryClass: getTypeClass(type),
                        core: false,
                        active: true,
                        adventure: true,
                        tier: null,
                        sessions: null,
                        type_label: null
                    };
                    doc.fullPath = resolveFullPath(doc);
                    discoveredDocs.push(doc);
                    console.log(`📄 Discovered adventure: ${known.file}`);
                }
            }
        } catch (_) { /* ignore */ }
    }

    // ─── Step 3: Try directory listing for subdirectories ──────────
    const subdirs = ['core', 'resources', 'adventures', 'expansions', 'travel', 'design', 'konreh', 'tollveil'];

    for (const subdir of subdirs) {
        try {
            const res = await fetch(DOCS_BASE_PATH + subdir + '/');
            if (res.ok) {
                const html = await res.text();
                const regex = /href="([^"]+\.html?)"/gi;
                let match;
                while ((match = regex.exec(html)) !== null) {
                    let fileName = match[1];
                    fileName = decodeURIComponent(fileName).replace(/^\/+/, '');
                    if (fileName === 'index.html' || fileName === 'manifest.json' || fileName === 'manifest-core.json') continue;
                    if (existingFileNames.has(fileName)) continue;
                    if (discoveredDocs.some(d => d.file === fileName)) continue;

                    const type = FOLDER_TO_TYPE[subdir] || 'other';
                    const title = fileName
                        .replace('.html', '')
                        .replace('.htm', '')
                        .replace(/_/g, ' ')
                        .replace(/-/g, ' ')
                        .replace(/\b\w/g, l => l.toUpperCase());

                    const doc = {
                        id: 'discovered_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4),
                        title: title,
                        file: fileName,
                        type: type,
                        folder: subdir,
                        path: DOCS_BASE_PATH + subdir + '/',
                        category: type,
                        categoryLabel: getTypeLabel(type),
                        categoryClass: getTypeClass(type),
                        core: type === 'core',
                        active: true,
                        adventure: type === 'adventures',
                        tier: null,
                        sessions: null,
                        type_label: null
                    };
                    doc.fullPath = resolveFullPath(doc);
                    discoveredDocs.push(doc);
                    console.log(`📄 Discovered from ${subdir}/: ${fileName}`);
                }
            }
        } catch (_) { /* ignore */ }
    }

    // ─── Step 4: Uploaded files from localStorage ────────────────
    try {
        const uploaded = localStorage.getItem('fates-edge-uploaded-docs');
        if (uploaded) {
            const parsed = JSON.parse(uploaded);
            for (const doc of parsed) {
                if (!doc.fullPath) {
                    doc.fullPath = resolveFullPath(doc);
                }
                const exists = allDocs.some(d => docsAreSame(d, doc));
                if (!exists && !discoveredDocs.some(d => docsAreSame(d, doc))) {
                    discoveredDocs.push(doc);
                    console.log(`📄 Found uploaded: ${doc.title}`);
                }
            }
        }
    } catch (_) { /* ignore */ }

    // ─── Step 5: Apply discoveries ─────────────────────────────────
    if (discoveredDocs.length > 0) {
        allDocs = [...allDocs, ...discoveredDocs];
        const seen = new Set();
        allDocs = allDocs.filter(d => {
            const key = d.fullPath || d.file;
            if (seen.has(key)) return false;
            seen.add(key);
            return true;
        });
        saveCache();
        refreshView();
        showToast(`📄 Added ${discoveredDocs.length} documents to library.`, 'success');
        console.log(`📚 Rebuilt cache: ${allDocs.length} total documents`);
    } else {
        if (allDocs.length === 0) {
            try {
                const res = await fetch(MANIFEST_CORE_PATH);
                if (res.ok) {
                    const coreManifest = await res.json();
                    const coreDocs = coreManifest.documents || [];
                    if (coreDocs.length > 0) {
                        allDocs = coreDocs.map(d => {
                            const type = d.category || d.section || 'other';
                            d.type = type;
                            d.folder = DOC_TYPES[type]?.folder || '';
                            d.fullPath = resolveFullPath(d);
                            return d;
                        });
                        saveCache();
                        refreshView();
                        showToast(`📄 Loaded ${allDocs.length} core documents.`, 'success');
                        console.log(`📚 Loaded ${allDocs.length} core documents as fallback.`);
                        return;
                    }
                }
            } catch (_) { /* ignore */ }
        }
        showToast('No new documents found.', 'info');
    }
}

// ============================================================
// THEME OBSERVER
// ============================================================

function setupThemeObserver() {
    if (window._themeObserver) {
        window._themeObserver.disconnect();
    }
    const observer = new MutationObserver(() => {
        const isLight = document.documentElement.classList.contains('light');
        isDarkMode = !isLight;
        if (currentBookDoc) {
            loadBookChapter(currentBookDoc, currentChapterIndex, true);
        } else if (currentDocPath) {
            loadDocument(currentDocPath, true);
        }
    });
    observer.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ['class']
    });
    window._themeObserver = observer;
}

// ============================================================
// EVENT LISTENERS
// ============================================================

function attachDocEvents() {
    const typeFilter = document.getElementById('docsTypeFilter');
    const searchInput = document.getElementById('docsSearchInput');
    const clearBtn = document.getElementById('docsClearFiltersBtn');
    const copyBtn = document.getElementById('doc-copy-url');
    const closeBtn = document.getElementById('doc-close-viewer');
    const refreshBtn = document.getElementById('doc-refresh-btn');
    const uploadBtn = document.getElementById('doc-upload-btn');
    const rebuildBtn = document.getElementById('doc-rebuild-btn');
    const chapterSelect = document.getElementById('doc-chapter-select');
    const chapterPrev = document.getElementById('doc-chapter-prev');
    const chapterNext = document.getElementById('doc-chapter-next');

    if (chapterSelect) {
        chapterSelect.addEventListener('change', function() {
            if (currentBookDoc) loadBookChapter(currentBookDoc, parseInt(this.value, 10));
        });
    }
    if (chapterPrev) {
        chapterPrev.addEventListener('click', function() {
            if (currentBookDoc && currentChapterIndex > 0) {
                loadBookChapter(currentBookDoc, currentChapterIndex - 1);
            }
        });
    }
    if (chapterNext) {
        chapterNext.addEventListener('click', function() {
            if (currentBookDoc && currentChapterIndex < currentBookDoc.pages.length - 1) {
                loadBookChapter(currentBookDoc, currentChapterIndex + 1);
            }
        });
    }

    if (typeFilter) typeFilter.addEventListener('change', applyDocsFilter);
    if (searchInput) searchInput.addEventListener('input', applyDocsFilter);

    if (clearBtn) {
        clearBtn.addEventListener('click', function() {
            // "Clear" only resets the search term now -- the category
            // dropdown always has one category selected (there's no "All"
            // option to clear back to), so leave it as the user set it.
            if (searchInput) searchInput.value = '';
            applyDocsFilter();
            if (searchInput) searchInput.focus();
        });
    }

    if (copyBtn) copyBtn.addEventListener('click', copyDocUrl);
    if (closeBtn) closeBtn.addEventListener('click', closeDocViewer);

    const printBtn = document.getElementById('doc-print-btn');
    if (printBtn) printBtn.addEventListener('click', () => printWithChromeHidden());

    if (refreshBtn) {
        refreshBtn.addEventListener('click', function() {
            localStorage.removeItem(CACHE_KEY);
            allDocs = [];
            loadDocs();
            showToast('🔄 Refreshed document list', 'info');
        });
    }

    if (uploadBtn) {
        uploadBtn.addEventListener('click', openUploadDialog);
    }

    if (rebuildBtn) {
        rebuildBtn.addEventListener('click', function() {
            if (confirm('Scan the filesystem for HTML documents in /data/docs/ and its subdirectories?')) {
                scanFilesystem();
            }
        });
    }
}

// ============================================================
// UPLOAD DIALOG
// ============================================================

let uploadHiddenSiblings = null;
function closeUploadDialog(modal) {
    modal.remove();
    if (uploadHiddenSiblings) {
        uploadHiddenSiblings.forEach(ch => { ch.style.display = ''; });
        uploadHiddenSiblings = null;
    }
}

function openUploadDialog() {
    // Inline editor screen — not a pop-up. Takes over the page in place of
    // whatever's currently shown.
    const modal = document.createElement('div');
    modal.className = 'editor-screen-host';
    modal.style.cssText = `
        display: flex; align-items: center; justify-content: center;
        padding: 1rem 0; animation: fadeIn 0.2s ease;
    `;

    const content = document.createElement('div');
    content.className = 'editor-screen';
    content.style.cssText = `
        max-width: 500px;
        width: 90%;
    `;

    const typeOptions = Object.entries(DOC_TYPES).map(([id, type]) => {
        const selected = id === 'adventures' ? 'selected' : '';
        return `<option value="${id}" ${selected}>${type.label}</option>`;
    }).join('');

    content.innerHTML = `
        <h3 style="color:var(--gold);margin-top:0;">📤 Upload Document</h3>
        <p style="color:var(--text2);font-size:0.85rem;">Upload a PDF or HTML document to add to the library.</p>

        <div style="margin:1rem 0;">
            <label style="display:block;font-size:0.85rem;font-weight:600;margin-bottom:0.3rem;">Document Title</label>
            <input id="upload-title" type="text" placeholder="Document title" style="width:100%;padding:0.4rem;background:var(--bg2);border:1px solid var(--border);border-radius:var(--radius);color:var(--text);" />
        </div>

        <div style="margin:1rem 0;">
            <label style="display:block;font-size:0.85rem;font-weight:600;margin-bottom:0.3rem;">Document Type</label>
            <select id="upload-type" style="width:100%;padding:0.4rem;background:var(--bg2);border:1px solid var(--border);border-radius:var(--radius);color:var(--text);">
                ${typeOptions}
            </select>
            <div style="font-size:0.65rem;color:var(--text3);margin-top:0.15rem;" id="upload-type-help">Documents are organized into subdirectories by type.</div>
        </div>

        <div style="margin:1rem 0;">
            <label style="display:block;font-size:0.85rem;font-weight:600;margin-bottom:0.3rem;">File (PDF or HTML)</label>
            <input id="upload-file" type="file" accept=".html,.htm,.pdf" style="width:100%;padding:0.4rem;background:var(--bg2);border:1px solid var(--border);border-radius:var(--radius);color:var(--text);" />
            <div style="font-size:0.7rem;color:var(--text3);margin-top:0.2rem;">Accepted formats: .html, .htm, .pdf</div>
        </div>

        <div style="display:flex;gap:0.5rem;margin-top:1rem;">
            <button id="upload-confirm-btn" class="btn btn-primary">📤 Upload</button>
            <button id="upload-cancel-btn" class="btn btn-secondary">Cancel</button>
        </div>
    `;

    modal.appendChild(content);
    const hostContainer = document.getElementById('app-content') || document.body;
    uploadHiddenSiblings = Array.from(hostContainer.children);
    uploadHiddenSiblings.forEach(ch => { ch.style.display = 'none'; });
    hostContainer.appendChild(modal);
    window.scrollTo({ top: 0 });

    if (!document.getElementById('upload-modal-styles')) {
        const style = document.createElement('style');
        style.id = 'upload-modal-styles';
        style.textContent = `
            @keyframes fadeIn {
                from { opacity: 0; transform: scale(0.95); }
                to { opacity: 1; transform: scale(1); }
            }
        `;
        document.head.appendChild(style);
    }

    const typeSelect = content.querySelector('#upload-type');
    if (typeSelect) {
        typeSelect.addEventListener('change', function() {
            const helpEl = document.getElementById('upload-type-help');
            if (helpEl && DOC_TYPES[this.value]) {
                helpEl.textContent = DOC_TYPES[this.value].description;
            }
        });
    }

    const cancelBtn = content.querySelector('#upload-cancel-btn');
    cancelBtn.addEventListener('click', () => closeUploadDialog(modal));

    const confirmBtn = content.querySelector('#upload-confirm-btn');
    confirmBtn.addEventListener('click', async () => {
        const title = document.getElementById('upload-title').value.trim();
        const type = document.getElementById('upload-type').value;
        const fileInput = document.getElementById('upload-file');

        if (!title) {
            showToast('Please enter a title.', 'error');
            return;
        }

        if (!fileInput.files || fileInput.files.length === 0) {
            showToast('Please select a file.', 'error');
            return;
        }

        const file = fileInput.files[0];
        const ext = file.name.split('.').pop().toLowerCase();

        if (!['html', 'htm', 'pdf'].includes(ext)) {
            showToast('Only HTML and PDF files are accepted.', 'error');
            return;
        }

        try {
            let content = null;
            if (ext === 'html' || ext === 'htm') {
                content = await file.text();
            }

            const safeName = title
                .toLowerCase()
                .replace(/[^a-z0-9]/g, '_')
                .replace(/_+/g, '_')
                .substring(0, 50) + '.' + ext;

            const typeInfo = DOC_TYPES[type] || DOC_TYPES.other;
            const folder = typeInfo.folder || '';

            const doc = {
                id: 'uploaded_' + Date.now(),
                title: title,
                file: safeName,
                type: type,
                folder: folder,
                path: DOCS_BASE_PATH + (folder ? folder + '/' : ''),
                category: type,
                categoryLabel: typeInfo.label,
                categoryClass: getTypeClass(type),
                core: type === 'core',
                active: true,
                uploaded: true,
                uploadedAt: new Date().toISOString(),
                adventure: type === 'adventures',
                tier: null,
                sessions: null,
                type_label: null,
                _content: content
            };
            doc.fullPath = resolveFullPath(doc);

            if (ext === 'pdf') {
                doc.isPDF = true;
            }

            const exists = allDocs.some(d => docsAreSame(d, doc));
            if (exists) {
                showToast('A document with this file already exists.', 'warning');
                closeUploadDialog(modal);
                return;
            }

            allDocs.push(doc);
            saveUploadedDoc(doc);
            saveCache();
            refreshView();
            closeUploadDialog(modal);
            showToast(`📤 Uploaded "${title}" to ${typeInfo.label}`, 'success');

        } catch (err) {
            showToast('Upload failed: ' + err.message, 'error');
        }
    });
}

function saveUploadedDoc(doc) {
    try {
        let uploaded = JSON.parse(localStorage.getItem('fates-edge-uploaded-docs') || '[]');
        uploaded = uploaded.filter(d => d.file !== doc.file);
        uploaded.push(doc);
        localStorage.setItem('fates-edge-uploaded-docs', JSON.stringify(uploaded));
    } catch (_) {}
}

// ============================================================
// APPLY FILTERS
// ============================================================

function renderDocCard(doc) {
    const isPDF = doc.isPDF || doc.file?.toLowerCase().endsWith('.pdf');
    const icon = doc.book ? '📖' : (isPDF ? '📄' : '📜');
    const typeInfo = DOC_TYPES[doc.type] || DOC_TYPES.other;
    const typeIcon = typeInfo.icon || '📄';
    const typeLabel = typeInfo.label || 'Other';
    const tierBadge = doc.tier ? `<span style="font-size:0.55rem;padding:0.05rem 0.3rem;border-radius:6px;background:var(--gold)33;color:var(--gold);border:1px solid var(--gold);">Tier ${doc.tier}</span>` : '';
    const sessionsBadge = doc.sessions ? `<span style="font-size:0.55rem;padding:0.05rem 0.3rem;border-radius:6px;background:var(--blue)33;color:var(--blue);border:1px solid var(--blue);">${doc.sessions} sessions</span>` : '';
    const pagesBadge = doc.book && Array.isArray(doc.pages) ? `<span style="font-size:0.6rem;color:var(--text2);">${doc.pages.length} chapters</span>` : '';

    return `
        <div class="doc-card" data-fullpath="${escHtml(doc.fullPath || '#')}"
             style="background:var(--bg3);border:1px solid var(--border);border-radius:var(--radius);padding:0.8rem;cursor:pointer;transition:all 0.15s;display:flex;flex-direction:column;justify-content:space-between;min-height:100%;">
            <div>
                <div style="font-size:1.5rem;margin-bottom:0.2rem;">${icon}</div>
                <h4 style="color:var(--gold);margin-bottom:0.3rem;font-size:0.95rem;font-weight:600;word-break:break-word;">${escHtml(doc.title)}</h4>
            </div>
            <div>
                <div class="doc-meta" style="font-size:0.75rem;color:var(--text2);display:flex;flex-wrap:wrap;gap:0.3rem;align-items:center;margin-top:0.3rem;">
                    <span class="doc-category-badge ${doc.type || 'other'}"
                          style="display:inline-block;padding:0.05rem 0.5rem;border-radius:12px;font-size:0.6rem;font-weight:600;background:var(--bg4);color:var(--text2);letter-spacing:0.02em;text-transform:uppercase;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%;">
                        ${typeIcon} ${escHtml(typeLabel)}
                    </span>
                    ${doc.core ? '<span style="font-size:0.6rem;color:var(--gold);font-weight:600;">⭐ Core</span>' : ''}
                    ${doc.uploaded ? '<span style="font-size:0.6rem;color:var(--green);font-weight:600;">📤</span>' : ''}
                    ${tierBadge}
                    ${sessionsBadge}
                    ${pagesBadge}
                </div>
                ${doc.description ? `<div style="font-size:0.65rem;color:var(--text3);margin-top:0.2rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escHtml(doc.description)}</div>` : ''}
            </div>
        </div>
    `;
}

function attachDocCardEvents(container) {
    container.querySelectorAll('.doc-card').forEach(card => {
        card.addEventListener('click', function() {
            const fullPath = this.dataset.fullpath;
            if (!fullPath || fullPath === '#') {
                showToast('Invalid document path.', 'error');
                return;
            }
            const doc = allDocs.find(d => (d.fullPath || '#') === fullPath);
            if (doc && doc.book) {
                openBookDocument(doc);
            } else {
                loadDocument(fullPath);
            }
        });

        card.addEventListener('mouseenter', function() {
            this.style.borderColor = 'var(--gold)';
            this.style.transform = 'translateY(-2px)';
        });
        card.addEventListener('mouseleave', function() {
            this.style.borderColor = 'var(--border)';
            this.style.transform = 'translateY(0)';
        });
    });
}

// ============================================================
// SINGLE-CATEGORY TILE PANE
// ============================================================
// One flat row (or one section per category, stacked) both turn into an
// unscannable/ever-taller wall as more guides/adventures/expansions are
// added. Instead there's one dropdown -- pick a category and the pane
// below swaps to just that category's tiles (6 wide, ~2 rows visible,
// scrolling internally past that) -- so the page height never depends on
// how many documents or categories exist.

function applyDocsFilter() {
    const typeFilter = document.getElementById('docsTypeFilter');
    const searchInput = document.getElementById('docsSearchInput');
    const container = document.getElementById('doc-list');
    if (!container) return;

    const type = typeFilter ? typeFilter.value : '';
    const search = searchInput ? searchInput.value.toLowerCase().trim() : '';

    if (!type) {
        container.innerHTML = `
            <div class="empty-state" style="color:var(--text2);text-align:center;padding:2rem;font-style:italic;">
                <div style="font-size:1.4rem;">📂</div>
                <p>Choose a category above to browse its documents.</p>
            </div>
        `;
        updateDocStats(0);
        return;
    }

    let filtered = allDocs.filter(d => d.type === type);
    if (search) {
        filtered = filtered.filter(d =>
            d.title.toLowerCase().includes(search) ||
            d.file.toLowerCase().includes(search) ||
            (d.author && d.author.toLowerCase().includes(search))
        );
    }

    updateDocStats(filtered.length);

    if (filtered.length === 0) {
        container.innerHTML = `
            <div class="empty-state" style="color:var(--text2);text-align:center;padding:2rem;font-style:italic;">
                <div style="font-size:1.4rem;">🔍</div>
                <p>No documents match your filters.</p>
                <p class="text-muted" style="font-size:0.85rem;">Try adjusting the category or search term.</p>
            </div>
        `;
        return;
    }

    container.innerHTML = `
        <div class="doc-grid">
            ${filtered.map(renderDocCard).join('')}
        </div>
    `;

    attachDocCardEvents(container);
}

// ============================================================
// CATEGORY DROPDOWN POPULATE
// ============================================================

function populateTypeFilter(docs) {
    const sel = document.getElementById('docsTypeFilter');
    if (!sel) return;

    const types = new Set();
    docs.forEach(d => { if (d.type) types.add(d.type); });

    const currentValue = sel.value;
    sel.innerHTML = '';

    const sortedTypes = Array.from(types).sort((a, b) => {
        const ia = TYPE_ORDER.indexOf(a);
        const ib = TYPE_ORDER.indexOf(b);
        if (ia === -1 && ib === -1) return a.localeCompare(b);
        if (ia === -1) return 1;
        if (ib === -1) return -1;
        return ia - ib;
    });

    sortedTypes.forEach(type => {
        const info = DOC_TYPES[type] || DOC_TYPES.other;
        const opt = document.createElement('option');
        opt.value = type;
        opt.textContent = info.label || type;
        sel.appendChild(opt);
    });

    // A category is always selected -- there's no "All" option, since the
    // whole point of the dropdown is to pick the one category whose tiles
    // populate the pane below. Keep whatever was already chosen if it's
    // still valid, otherwise default to the first category.
    if (currentValue && sortedTypes.includes(currentValue)) {
        sel.value = currentValue;
    } else if (sortedTypes.length > 0) {
        sel.value = sortedTypes[0];
    }
}

function updateDocStats(count) {
    const statsEl = document.getElementById('docsFilterStats');
    if (statsEl) {
        const total = allDocs.length;
        statsEl.textContent = count === total ? `${total} documents` : `${count} of ${total} documents`;
    }
}

function updateTotalCount() {
    const el = document.getElementById('docsTotalCount');
    if (el) {
        el.textContent = `${allDocs.length} documents`;
    }
}

// ============================================================
// BOOK DOCUMENTS (multi-page: GM Guide, Player's Guide, ...)
// ============================================================
// A book's manifest entry carries a `pages` array (from book.json, written
// by tools/generate_book_index.py in the docs repo). Opening one shows a
// single document view with a chapter nav bar instead of dozens of
// separate library rows -- clicking "GM Guide" reads as opening one book,
// not choosing among 25 unrelated documents.

function openBookDocument(doc) {
    currentBookDoc = doc;
    loadBookChapter(doc, 0);
}

function updateChapterNav(doc, chapterIndex) {
    const nav = document.getElementById('doc-chapter-nav');
    const select = document.getElementById('doc-chapter-select');
    const prevBtn = document.getElementById('doc-chapter-prev');
    const nextBtn = document.getElementById('doc-chapter-next');
    if (!nav || !select || !prevBtn || !nextBtn) return;

    nav.style.display = 'flex';
    select.innerHTML = doc.pages.map((p, i) =>
        `<option value="${i}">${escHtml(p.label ? `${p.label}: ${p.title}` : p.title)}</option>`
    ).join('');
    select.value = String(chapterIndex);

    prevBtn.disabled = chapterIndex <= 0;
    nextBtn.disabled = chapterIndex >= doc.pages.length - 1;
    prevBtn.style.opacity = prevBtn.disabled ? '0.4' : '1';
    nextBtn.style.opacity = nextBtn.disabled ? '0.4' : '1';
}

function hideChapterNav() {
    const nav = document.getElementById('doc-chapter-nav');
    if (nav) nav.style.display = 'none';
}

function loadBookChapter(doc, chapterIndex, preserveTheme = false) {
    if (!doc || !Array.isArray(doc.pages) || !doc.pages[chapterIndex]) return;

    currentBookDoc = doc;
    currentChapterIndex = chapterIndex;
    const chapter = doc.pages[chapterIndex];

    const viewerContainer = document.getElementById('doc-viewer-container');
    const viewer = document.getElementById('doc-viewer');
    const titleEl = document.getElementById('doc-viewer-title');
    if (!viewerContainer || !viewer || !titleEl) return;

    const basePath = doc.path.endsWith('/') ? doc.path : doc.path + '/';
    const chapterPath = basePath + chapter.file;
    currentDocPath = chapterPath;

    viewerContainer.style.display = 'block';
    updateChapterNav(doc, chapterIndex);
    titleEl.textContent = preserveTheme ? titleEl.textContent : 'Loading…';
    if (!preserveTheme) {
        viewer.innerHTML = '<div class="loading" style="display:flex;align-items:center;justify-content:center;height:100%;min-height:400px;color:var(--text2);font-style:italic;padding:2rem;">Loading chapter…</div>';
    }

    fetch(chapterPath)
        .then(res => {
            if (!res.ok) throw new Error(`HTTP ${res.status}`);
            return res.text();
        })
        .then(html => {
            if (isSpaContent(html)) {
                viewer.innerHTML = `
                    <div class="empty-state" style="color:var(--text2);text-align:center;padding:2rem;">
                        <div style="font-size:2rem;">🚫</div>
                        <p>Could not load chapter.</p>
                        <p class="text-muted" style="font-size:0.75rem;">Path: ${escHtml(chapterPath)}</p>
                    </div>
                `;
                titleEl.textContent = 'Error';
                return;
            }
            const sanitized = sanitizeHtml(html);
            viewer.innerHTML = injectThemeAndStyles(sanitized, chapterPath);
            titleEl.textContent = `${doc.title} — ${chapter.label ? `${chapter.label}: ` : ''}${chapter.title}`;
            if (!preserveTheme) {
                showToast(`📖 Loaded: ${chapter.title}`, 'success');
            }
        })
        .catch(err => {
            console.error('Chapter load error:', err);
            viewer.innerHTML = `
                <div class="empty-state" style="color:var(--text2);text-align:center;padding:2rem;">
                    <div style="font-size:2rem;">❌</div>
                    <p>Could not load chapter.</p>
                    <p class="text-muted" style="font-size:0.85rem;">${escHtml(err.message)}</p>
                </div>
            `;
            titleEl.textContent = 'Error';
            showToast(`Failed to load chapter: ${err.message}`, 'error');
        });
}

// ============================================================
// LOAD DOCUMENT
// ============================================================

export function loadDocument(docPath, preserveTheme = false) {
    currentDocPath = docPath;
    currentBookDoc = null;
    currentChapterIndex = -1;
    hideChapterNav();
    const viewerContainer = document.getElementById('doc-viewer-container');
    const viewer = document.getElementById('doc-viewer');
    const titleEl = document.getElementById('doc-viewer-title');
    if (!viewerContainer || !viewer || !titleEl) return;

    viewerContainer.style.display = 'block';
    titleEl.textContent = 'Loading…';
    viewer.innerHTML = '<div class="loading" style="display:flex;align-items:center;justify-content:center;height:100%;min-height:400px;color:var(--text2);font-style:italic;padding:2rem;">Loading document…</div>';

    let doc = allDocs.find(d => d.fullPath === docPath || d.file === docPath);
    if (!doc) {
        const fileName = docPath.split('/').pop();
        doc = allDocs.find(d => d.file === fileName);
        if (!doc) {
            doc = allDocs.find(d => d.fullPath && d.fullPath.endsWith(docPath));
        }
    }

    // Show the Print button only for the docs it's actually meant for --
    // see PRINTABLE_DOC_IDS's comment above. Set once here (rather than in
    // each render branch below) so it stays correct regardless of which
    // branch ends up rendering this doc.
    const printBtn = document.getElementById('doc-print-btn');
    if (printBtn) {
        printBtn.style.display = (doc && PRINTABLE_DOC_IDS.has(doc.id)) ? '' : 'none';
    }

    if (doc && doc.isPDF) {
        let pdfUrl = doc.fullPath || docPath;
        if (pdfUrl && !pdfUrl.startsWith('http') && !pdfUrl.startsWith('/')) {
            pdfUrl = '/' + pdfUrl.replace(/^\.?\/+/, '');
        }

        viewer.innerHTML = `
            <div style="display:flex;flex-direction:column;height:100%;min-height:500px;">
                <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:0.5rem;padding:0.5rem 0;border-bottom:1px solid var(--border);margin-bottom:0.5rem;">
                    <div style="display:flex;gap:0.5rem;align-items:center;">
                        <span style="font-size:1.2rem;">📄</span>
                        <span style="font-weight:600;font-size:1rem;">${escHtml(doc.title)}</span>
                        <span class="badge badge-blue">PDF</span>
                    </div>
                    <div style="display:flex;gap:0.3rem;">
                        <button class="btn btn-sm btn-primary" onclick="window.open('${escHtml(pdfUrl)}', '_blank')">📤 Open in New Tab</button>
                        <button class="btn btn-sm btn-secondary" onclick="window.location.href='${escHtml(pdfUrl)}'">💾 Download</button>
                    </div>
                </div>
                <div style="flex:1;min-height:450px;background:var(--bg3);border-radius:var(--radius);overflow:hidden;">
                    <iframe
                        src="${escHtml(pdfUrl)}"
                        style="width:100%;height:100%;min-height:450px;border:none;background:var(--bg3);"
                        allow="fullscreen"
                        sandbox="allow-same-origin"
                        loading="lazy"
                    ></iframe>
                    <!-- Sandbox note: only allow-same-origin is granted, so the
                         browser's built-in PDF viewer can actually fetch/render
                         a same-origin file. allow-scripts is deliberately
                         omitted -- the PDF viewer doesn't need script execution
                         to render, and allow-same-origin + allow-scripts
                         together is the combination that lets sandboxed
                         content script its way back out of the sandbox. -->
                </div>
                <div style="font-size:0.65rem;color:var(--text3);padding:0.3rem 0;text-align:center;">
                    If the PDF does not display, your browser may not support embedded PDF viewing. 
                    Use the "Open in New Tab" button above.
                </div>
            </div>
        `;
        titleEl.textContent = doc.title + ' (PDF)';
        return;
    }

    if (doc && doc._content) {
        const sanitized = sanitizeHtml(doc._content);
        if (isSpaContent(sanitized)) {
            viewer.innerHTML = `
                <div class="empty-state" style="color:var(--text2);text-align:center;padding:2rem;min-width:100%;">
                    <div style="font-size:2rem;">🚫</div>
                    <p>Could not load document.</p>
                    <p class="text-muted" style="font-size:0.85rem;">The cached content appears to be the application page, not a document.</p>
                    <p class="text-muted" style="font-size:0.75rem;">Document: ${escHtml(doc.title)}</p>
                    <button class="btn btn-sm btn-primary" onclick="window.location.reload()" style="margin-top:0.5rem;">🔄 Reload</button>
                </div>
            `;
            titleEl.textContent = 'Error';
            showToast('Cached content is invalid – please refresh.', 'error');
            return;
        }
        const themedHtml = injectThemeAndStyles(sanitized, docPath);
        viewer.innerHTML = themedHtml;
        titleEl.textContent = doc.title;
        showToast(`📄 Loaded: ${titleEl.textContent}`, 'success');
        return;
    }

    let fetchPath = doc ? doc.fullPath : docPath;

    if (fetchPath && !fetchPath.startsWith('http') && !fetchPath.startsWith('/')) {
        fetchPath = '/' + fetchPath.replace(/^\.?\/+/, '');
    }

    if (fetchPath) {
        fetchPath = fetchPath.replace(/\/+/g, '/').replace(/\s/g, '');
    }

    if (!fetchPath || fetchPath === '/' || fetchPath === DOCS_BASE_PATH) {
        if (doc && doc.file) {
            const folder = doc.folder ? doc.folder + '/' : '';
            fetchPath = DOCS_BASE_PATH + folder + doc.file.replace(/^\/+/, '');
        } else {
            showToast('Could not determine document path.', 'error');
            return;
        }
    }

    console.log(`📄 Loading: ${fetchPath}`);

    fetch(fetchPath)
        .then(res => {
            if (!res.ok) throw new Error(`HTTP ${res.status}`);
            return res.text();
        })
        .then(html => {
            if (isSpaContent(html)) {
                viewer.innerHTML = `
                    <div class="empty-state" style="color:var(--text2);text-align:center;padding:2rem;min-width:100%;">
                        <div style="font-size:2rem;">🚫</div>
                        <p>Could not load document.</p>
                        <p class="text-muted" style="font-size:0.85rem;">The server returned the application page instead of the document.</p>
                        <p class="text-muted" style="font-size:0.75rem;">Path: ${escHtml(fetchPath)}</p>
                        <p class="text-muted" style="font-size:0.75rem;">Make sure the file exists in /data/docs/ and is accessible.</p>
                        <button class="btn btn-sm btn-primary" onclick="window.location.reload()" style="margin-top:0.5rem;">🔄 Reload</button>
                    </div>
                `;
                titleEl.textContent = 'Error';
                showToast('Failed to load document – server returned SPA.', 'error');
                return;
            }

            const sanitized = sanitizeHtml(html);
            const themedHtml = injectThemeAndStyles(sanitized, fetchPath);
            viewer.innerHTML = themedHtml;

            if (doc) {
                titleEl.textContent = doc.title;
            } else {
                const filename = fetchPath.split('/').pop().replace('.html', '').replace(/_/g, ' ');
                titleEl.textContent = filename;
            }

            showToast(`📄 Loaded: ${titleEl.textContent}`, 'success');
        })
        .catch(err => {
            console.error('Document load error:', err);
            viewer.innerHTML = `
                <div class="empty-state" style="color:var(--text2);text-align:center;padding:2rem;min-width:100%;">
                    <div style="font-size:2rem;">❌</div>
                    <p>Could not load document.</p>
                    <p class="text-muted" style="font-size:0.85rem;">${err.message}</p>
                    <p class="text-muted" style="font-size:0.75rem;">Path: ${escHtml(fetchPath)}</p>
                    <button class="btn btn-sm btn-primary" onclick="location.reload()" style="margin-top:0.5rem;">🔄 Reload</button>
                </div>
            `;
            titleEl.textContent = 'Error';
            showToast(`Failed to load document: ${err.message}`, 'error');
        });
}

// ============================================================
// THEME INJECTION
// ============================================================

function injectThemeAndStyles(content, docPath) {
    const isLight = document.documentElement.classList.contains('light');
    const themeClass = isLight ? 'light' : 'dark';

    return `
        <div class="integrated-document ${themeClass}" style="
            font-family: var(--font, 'Georgia', serif);
            line-height: 1.7;
            color: var(--text, #222);
            background: var(--bg, #fafaf6);
            padding: 0.5rem;
            max-width: 100%;
        ">
            <style>
                .integrated-document {
                    --bg: ${isLight ? '#fafafa' : '#0d0b0f'};
                    --bg2: ${isLight ? '#eaeaea' : '#18141c'};
                    --bg3: ${isLight ? '#dfdfdf' : '#231e29'};
                    --bg4: ${isLight ? '#d3d3d3' : '#2f2838'};
                    --text: ${isLight ? '#212121' : '#e6dce8'};
                    --text2: ${isLight ? '#555555' : '#b8aabf'};
                    --gold: ${isLight ? '#b8860b' : '#d4af37'};
                    --border: ${isLight ? '#bbbbbb' : '#3a3242'};
                    --accent: ${isLight ? '#8b5e3c' : '#c99a6b'};
                }
                .integrated-document h1 { font-size: 2.2rem; margin-top: 0; border-bottom: 2px solid var(--border); padding-bottom: 0.3rem; color: var(--text); }
                .integrated-document h2 { font-size: 1.8rem; margin-top: 1.5rem; border-bottom: 1px solid var(--border); padding-bottom: 0.2rem; color: var(--text); }
                .integrated-document h3 { font-size: 1.4rem; margin-top: 1.2rem; color: var(--text); }
                .integrated-document h4 { font-size: 1.2rem; margin-top: 1rem; color: var(--text); }
                .integrated-document p { margin: 0.8rem 0; color: var(--text); }
                .integrated-document ul, .integrated-document ol { margin: 0.8rem 0 0.8rem 1.5rem; color: var(--text); }
                .integrated-document li { margin: 0.3rem 0; }
                .integrated-document blockquote { margin: 1rem 0; padding: 0.5rem 1.5rem; border-left: 4px solid var(--gold); background: var(--bg3); color: var(--text2); }
                .integrated-document table { border-collapse: collapse; width: 100%; margin: 1rem 0; font-size: 0.95rem; }
                .integrated-document th, .integrated-document td { border: 1px solid var(--border); padding: 0.5rem 0.8rem; text-align: left; color: var(--text); }
                .integrated-document th { background: var(--bg3); color: var(--gold); }
                .integrated-document code { background: var(--bg3); padding: 0.2rem 0.4rem; border-radius: 4px; font-size: 0.9rem; color: var(--text); }
                .integrated-document pre { background: var(--bg3); padding: 1rem; border-radius: 6px; overflow-x: auto; font-size: 0.9rem; color: var(--text); }
                .integrated-document img { max-width: 100%; height: auto; }
                .integrated-document a { color: var(--gold); text-decoration: none; }
                .integrated-document a:hover { text-decoration: underline; }
                @media (max-width: 768px) {
                    .integrated-document h1 { font-size: 1.8rem; }
                    .integrated-document h2 { font-size: 1.5rem; }
                    .integrated-document h3 { font-size: 1.2rem; }
                }
            </style>
            <div class="document-content">${content}</div>
        </div>
    `;
}

// ============================================================
// CLOSE VIEWER
// ============================================================

export function closeDocViewer() {
    const container = document.getElementById('doc-viewer-container');
    const viewer = document.getElementById('doc-viewer');
    if (container) container.style.display = 'none';
    if (viewer) viewer.innerHTML = '<div class="loading" style="display:flex;align-items:center;justify-content:center;height:100%;min-height:400px;color:var(--text2);font-style:italic;padding:2rem;">Select a document to view.</div>';
    currentDocPath = null;
    currentBookDoc = null;
    currentChapterIndex = -1;
    hideChapterNav();
}

// ============================================================
// COPY URL
// ============================================================

export function copyDocUrl() {
    if (!currentDocPath) {
        showToast('No document loaded.', 'error');
        return;
    }

    let url = currentDocPath;
    if (url && !url.startsWith('http')) {
        if (!url.startsWith('/')) {
            url = '/' + url.replace(/^\.?\/+/, '');
        }
        url = window.location.origin + url;
    }

    navigator.clipboard.writeText(url)
        .then(() => showToast('Document URL copied!', 'success'))
        .catch(() => {
            prompt('Copy this URL:', url);
        });
}

// ============================================================
// REFRESH VIEW
// ============================================================

function refreshView() {
    const list = document.getElementById('doc-list');
    if (list) {
        populateTypeFilter(allDocs);
        applyDocsFilter();
        updateDocStats(allDocs.length);
        updateTotalCount();
    }
}

// ============================================================
// LIFECYCLE
// ============================================================

export function onActivate() {
    console.log('[Docs] Activated');
    if (allDocs.length === 0) {
        loadDocs();
    } else {
        refreshView();
    }
}

export function onDeactivate() {
    console.log('[Docs] Deactivated');
}

export function refresh() {
    localStorage.removeItem(CACHE_KEY);
    allDocs = [];
    loadDocs();
}

export function destroy() {
    if (window._themeObserver) {
        window._themeObserver.disconnect();
        window._themeObserver = null;
    }
    allDocs = [];
    currentDocPath = null;
    container = null;
}